// The vector catalog of packages/contracts, `src/vectors/catalog.ts`: every
// vendored vector, imported for the test-only entry. Written by
// tools/generate-contracts.ts with the other generated files.

import { join } from "node:path";

import { findFiles } from "./workspace.ts";

/** The banner of every generated file of packages/contracts. */
export const BANNER = (source: string): string =>
  `// Generated by tools/generate-contracts.ts from ${source}.\n// Do not edit: run \`pnpm exec tsx tools/generate-contracts.ts --write\`.\n`;

/** The name a vector is exported under: its file name without `.json`. */
const vectorName = (file: string): string => {
  const match = /^([a-z0-9][a-z0-9-]*)\.json$/u.exec(file);
  if (match?.[1] === undefined)
    throw new Error(`vector file name is not kebab-case: ${file}`);
  return match[1];
};

/** The text of `src/vectors/catalog.ts` for the vectors under `packageDir`. */
export const catalogSource = (packageDir: string): string => {
  const root = join(packageDir, "src", "vectors");
  const lines = [
    BANNER("the vendored files under src/vectors/"),
    "// Test-only: only the `testing` entry imports this module.\n",
  ];
  let counter = 0;
  /** Import every file of a folder under src/vectors/; its members by name. */
  const folderGroup = (folder: string, key: string): string => {
    const names = findFiles(join(root, folder), () => true);
    const members: string[] = [];
    for (const file of names) {
      const identifier = `vector${String(counter)}`;
      counter += 1;
      lines.push(
        `import ${identifier} from "./${folder}/${file}" with { type: "json" };`,
      );
      members.push(`    ${JSON.stringify(vectorName(file))}: ${identifier},`);
    }
    return `  ${key}: {\n${members.join("\n")}\n  },`;
  };
  // Each folder under src/vectors/snapshot/ and the key it is exported under.
  const snapshotFolders = [
    ["valid", "valid"],
    ["invalid", "invalid"],
    ["signature", "signature"],
    ["typed-data", "typedData"],
    ["signed-action", "signedAction"],
  ] as const;
  const snapshotGroups = snapshotFolders.map(([kind, key]) =>
    folderGroup(`snapshot/${kind}`, key),
  );
  // Each kernel version's folder under src/vectors/kernel/.
  const kernelGroups = [folderGroup("kernel/v1", "v1")];
  lines.push(
    'import signing from "./signing.json" with { type: "json" };',
    'import keyDelegationV1 from "./key-delegation/v1/vectors.json" with { type: "json" };',
    "",
    "/** Every vector is data of unknown shape: a consumer validates what it reads. */",
    "export type VectorSet = Readonly<Record<string, unknown>>;",
    "",
    "export type SnapshotVectors = {",
    "  readonly valid: VectorSet;",
    "  readonly invalid: VectorSet;",
    "  /** Schema-valid Snapshots with the verdict of the shell's W-26 checks. */",
    "  readonly signature: VectorSet;",
    "  /** The canonical typedData bytes of signed actions, from their fields. */",
    "  readonly typedData: VectorSet;",
    "  /**",
    "   * Signed actions made by an independent signer: the EIP-712 message, its",
    "   * hashes, and the signature, from a public test key.",
    "   */",
    "  readonly signedAction: VectorSet;",
    "};",
    "",
    "export type KernelVectors = {",
    "  /** The SuperEngine fairness kernel, kernelVersion 1: its public sets, by file name. */",
    "  readonly v1: VectorSet;",
    "};",
    "",
    "export type KeyDelegationVectors = {",
    "  /** The key-delegation contract `key-delegation/v1`: its vectors file. */",
    "  readonly v1: unknown;",
    "};",
    "",
    "export const signingVectors: unknown = signing;",
    "",
    `export const snapshotVectors: SnapshotVectors = {\n${snapshotGroups.join("\n")}\n};`,
    "",
    `export const kernelVectors: KernelVectors = {\n${kernelGroups.join("\n")}\n};`,
    "",
    "export const keyDelegationVectors: KeyDelegationVectors = { v1: keyDelegationV1 };",
    "",
  );
  return lines.join("\n");
};
